alter table public.payment_requests drop constraint if exists payment_requests_payroll_submission_snapshot_check; alter table public.payment_requests add constraint payment_requests_payroll_submission_snapshot_check check (request_type::text <> 'nomina' or status::text = 'draft' or (approver_id is not null and approver_selection_source = any (array['assigned'::text,'approval_rules'::text]) and submitted_at is not null) or (no_presupuestal is true and status::text in ('approved','finance_validation','scheduled','paid') and approver_id is null and approver_assignment_id is null and approver_selection_source is null and submitted_at is null and approved_by is not null and approved_at is not null));